    {"symbol": "⚖️", "tooltip": "Liability is the spine that converts voluntary safety promises into enforceable obligations, like the scale that only works if both pans are bolted to the beam."},
    {"symbol": "🛫", "tooltip": "The FAA's airworthiness directives surface aircraft failures without waiting for crash litigation — the model for incident reporting that feeds harms litigation never reaches."},
    {"symbol": "🚧", "tooltip": "Where harm exceeds any balance sheet, ex-post pricing fails and you need a gate before deployment, not a bill after the crash."}
  ],
  "claim_sketches": [
    {"claim": "The small-dollar injury never reaches the actuary's spreadsheet — but that gap argues for augmenting liability with mandatory incident reporting, not abandoning it.", "targets": ["AN-3", "AN-5"], "relationship": "concedes_and_pivots"},
    {"claim": "Index strict-liability attachment to ex-ante-defined high-stakes domains the way financial regulation triggers tiered scrutiny at named asset thresholds — that delivers the predictable exposure the Accelerationist demands.", "targets": ["AN-6"], "relationship": "specifies"},
    {"claim": "Strict liability outperforms negligence under one specifiable condition: where harm is irreversible and post-hoc attribution is feasible, and the reasonable-developer test has nothing to measure against.", "targets": [], "relationship": ""},
    {"claim": "Where expected harm exceeds any developer's plausible solvency, the marginal deterrent value of additional liability approaches zero — you cannot deter a harm no balance sheet can absorb.", "targets": [], "relationship": ""},
    {"claim": "Disclosure decoupled from litigation kills the document-suppression incentive — a firm cannot shrink the plaintiff's paper trail when the reporting obligation exists independent of any lawsuit.", "targets": ["AN-4"], "relationship": "concedes_and_pivots"}
  ]
}

