    {"claim_id": "C1", "claim": "Both strict liability and negligence are claims-driven machines: they deter loudest where harm is rare and visible, and go silent where harm is most common and diffuse, because the diffuse small-dollar injury never reaches the actuary's spreadsheet.", "claimant": "skeptic", "type": "empirical", "supported_by": [{"claim_id": "C2", "scheme": "argument_from_evidence", "warrant": "Survey evidence that a large share of affected people never learn an algorithm touched their file establishes that no claim ever forms for diffuse harm."}], "attacked_by": [
      {"claim_id": "C12", "claim": "The gap argues for augmenting liability with disclosure and continuous monitoring, not abandoning it; the FAA's airworthiness directives and FDA market-withdrawal reporting surface harms litigation never reaches.", "claimant": "safetyist", "attack_type": "undercut", "scheme": "DISTINGUISH", "argumentation_scheme": "ARGUMENT_FROM_ANALOGY", "critical_question_addressed": 1}
