    {"claim_id": "C2", "claim": "A person denied a loan or flagged by a screening model often never learns an AI decision touched them, so there is no lawsuit, no claim, and no premium adjustment.", "claimant": "skeptic", "type": "empirical", "supported_by": [], "attacked_by": []},
    {"claim_id": "C3", "claim": "Liability is already domain-calibrated everywhere it operates — a surgeon answers to malpractice, a trucker to near-strict traffic rules, a bank custodian to fiduciary duty — so no single horizontal strict-versus-negligence standard should govern AI.", "claimant": "skeptic", "type": "normative", "supported_by": [{"claim_id": "C4", "scheme": "argument_from_precedent", "warrant": "Existing sectoral regimes demonstrate that legal systems already vary the standard by causal chain and harm type."}], "attacked_by": []},
    {"claim_id": "C4", "claim": "The component-part doctrine that lets a brake manufacturer share liability strains for AI because a foundation model is non-rivalrous: the same weights splinter into thousands of divergent runtime states downstream, severing the proximate-cause chain upstream liability assumes.", "claimant": "skeptic", "type": "empirical", "supported_by": [], "attacked_by": [
      {"claim_id": "C22", "claim": "The deployer pays first, then recovers against the developer whose training defect caused the harm, capped at the deployer's actual paid liability — a known, priceable quantity.", "claimant": "safetyist", "attack_type": "rebut", "scheme": "DISTINGUISH", "argumentation_scheme": "PRACTICAL_REASONING", "critical_question_addressed": 2}
    ]},
    {"claim_id": "C5", "claim": "Strict liability can push a firm to document less and disclose less, to shrink the paper trail a plaintiff would use — the moral-hazard direction nobody on the optimist or safetyist side wants to say out loud.", "claimant": "skeptic", "type": "empirical", "supported_by": [], "attacked_by": [
