    {"claim_id": "C6", "claim": "'This will chill innovation' is a claim, not a fact; I have not seen hard counts showing liability exposure, rather than compliance-cost asymmetry, slowed a single AI product to market.", "claimant": "skeptic", "type": "empirical", "supported_by": [], "attacked_by": [
      {"claim_id": "C8", "claim": "What chills beneficial deployment is not the severity of liability but the unpredictability of exposure — a developer can price a known risk but cannot price an open-ended foreseeability standard.", "claimant": "accelerationist", "attack_type": "rebut", "scheme": "REFRAME", "argumentation_scheme": "PRACTICAL_REASONING", "critical_question_addressed": 1}
    ]},
    {"claim_id": "C7", "claim": "In the attributable catastrophic case — the AV that kills a pedestrian, where causation is clean and the defendant is identifiable — strict liability deters and compensates better than making an injured family prove a software engineer was careless, but that band is narrow.", "claimant": "skeptic", "type": "normative", "supported_by": [], "attacked_by": []},
    {"claim_id": "C8", "claim": "What chills beneficial deployment is not the severity of liability but the unpredictability of exposure; broad discretionary negligence and uniform strict liability fail the same way because both leave the deployer unable to calculate exposure before shipping.", "claimant": "accelerationist", "type": "empirical", "supported_by": [{"claim_id": "C9", "scheme": "argument_from_consequences", "warrant": "If a deployer cannot calculate exposure, beneficial deployments get over-deterred, producing uncounted harm among people a tool never reached."}], "attacked_by": [
      {"claim_id": "C20", "claim": "The operative axis is not unpredictability or reversibility but whether a claim stream ever forms; in the diffuse band claims structurally never arrive, so the tort cycle never starts.", "claimant": "safetyist", "attack_type": "undercut", "scheme": "REFRAME", "argumentation_scheme": "PRACTICAL_REASONING", "critical_question_addressed": 1}
