    {"claim_id": "C9", "claim": "Every diffuse-benefit deployment that uniform strict liability over-deters has a body count among the patients a diagnostic tool never reached and the drivers a safer system never protected — real cost even though no one files a claim.", "claimant": "accelerationist", "type": "normative", "supported_by": [], "attacked_by": []},
    {"claim_id": "C10", "claim": "Insurers are the most precise deterrence engine for harms that surface: experience-rated premiums reprice loss history continuously, and workers'-comp insurers cut workplace fatalities by pricing risk before courts ever weighed in.", "claimant": "accelerationist", "type": "empirical", "supported_by": [{"claim_id": "C10s", "scheme": "argument_from_precedent", "warrant": "The workers'-comp precedent shows market pricing deterred a class of harm faster than litigation."}], "attacked_by": [
