    {"claim_id": "C22", "claim": "The deployer pays first, then recovers against the developer whose training defect caused the harm, capped at the deployer's actual paid liability — a known, priceable quantity, not an open-ended volume trigger.", "claimant": "safetyist", "type": "normative", "supported_by": [], "attacked_by": []},
    {"claim_id": "C23", "claim": "An audit sees only what its scope is built to measure; whoever sets the aperture decides what counts as harm, so a standardized audit fires loudest on legible harms and goes silent on the diffuse residual nobody wrote a test for — the visibility bias relocates one layer upstream into the terms of reference.", "claimant": "skeptic", "type": "empirical", "supported_by": [{"claim_id": "C23s", "scheme": "argument_from_evidence", "warrant": "A point-in-time weight-audit cannot detect a 9-point racial gap that only emerges across deployment-population data the auditor never holds."}], "attacked_by": [
      {"claim_id": "C26", "claim": "The drift objection does not refute audit-gating; it specifies what the gate has to be — a periodic, population-held re-audit clock running against held deployment data plus a community-weighted, statutorily locked aperture catches the gap a one-shot weight-audit misses.", "claimant": "safetyist", "attack_type": "rebut", "scheme": "DISTINGUISH", "argumentation_scheme": "PRACTICAL_REASONING", "critical_question_addressed": 2}
