    {"claim_id": "C24", "claim": "A reporting clock with no liability consequence for non-reporting decays into compliance theater, the way the FAA delegating certification to Boeing contributed to 346 deaths; liability is what gives the disclosure clock teeth.", "claimant": "safetyist", "type": "empirical", "supported_by": [], "attacked_by": []},
    {"claim_id": "C25", "claim": "Audit findings and disclosures are not cumulative — a firm publishes a fairness metric one year and removes it the next, documented across multiple developers' model cards — so without a statutory irreversibility lock, audit-gating decays into the same compliance theater the toothless reporting clock produces.", "claimant": "skeptic", "type": "empirical", "supported_by": [], "attacked_by": [
